using System.Collections;
using UnityEngine;

/// <summary>
/// Lightweight procedural animation controller for the Clockwork Barrel Golem.
/// Add this to the imported model root or use the prefab generated by the Editor menu.
/// </summary>
public sealed class ClockworkGolemAnimator : MonoBehaviour
{
    [Header("Pivot references (the prefab builder fills these automatically)")]
    public Transform headPivot;
    public Transform leftArmPivot;
    public Transform rightArmPivot;
    public Transform chestDoorPivot;
    public Transform cannonSlide;
    public Transform pedalDrivePivot;

    [Header("Idle motion")]
    public bool idleHeadScan = true;
    public bool spinPedals = true;
    [Min(0f)] public float headScanAngle = 22f;
    [Min(0f)] public float headScanSpeed = 0.7f;
    public float pedalDegreesPerSecond = 190f;
    public float animationResponse = 9f;

    [Header("Controls")]
    [Range(-90f, 90f)] public float headYawDegrees;
    public float leftArmRollDegrees;
    public float rightArmRollDegrees;
    public bool chestOpen;
    [Range(45f, 125f)] public float chestOpenAngle = 108f;
    [Min(0f)] public float cannonDeployDistance = 0.58f;

    private Vector3 cannonClosedPosition;
    private Quaternion doorClosedRotation;
    private float pedalAngle;
    private float cannonRecoil;
    private bool firing;

    private void Awake()
    {
        ResolvePivots();
        if (cannonSlide != null) cannonClosedPosition = cannonSlide.localPosition;
        if (chestDoorPivot != null) doorClosedRotation = chestDoorPivot.localRotation;
    }

    private void OnValidate()
    {
        ResolvePivots();
    }

    private void Update()
    {
        if (headPivot != null)
        {
            float idleYaw = idleHeadScan ? Mathf.Sin(Time.time * headScanSpeed) * headScanAngle : 0f;
            headPivot.localRotation = Quaternion.Euler(0f, headYawDegrees + idleYaw, 0f);
        }

        if (leftArmPivot != null)
            leftArmPivot.localRotation = Quaternion.AngleAxis(leftArmRollDegrees, Vector3.right);

        if (rightArmPivot != null)
            rightArmPivot.localRotation = Quaternion.AngleAxis(rightArmRollDegrees, Vector3.right);

        if (spinPedals)
            pedalAngle = Mathf.Repeat(pedalAngle + pedalDegreesPerSecond * Time.deltaTime, 360f);

        if (pedalDrivePivot != null)
            pedalDrivePivot.localRotation = Quaternion.AngleAxis(pedalAngle, Vector3.forward);

        if (chestDoorPivot != null)
        {
            Quaternion target = chestOpen
                ? doorClosedRotation * Quaternion.Euler(0f, -chestOpenAngle, 0f)
                : doorClosedRotation;
            chestDoorPivot.localRotation = Quaternion.Slerp(
                chestDoorPivot.localRotation, target, Time.deltaTime * animationResponse);
        }

        if (cannonSlide != null)
        {
            Vector3 target = cannonClosedPosition
                + Vector3.forward * (chestOpen ? cannonDeployDistance : 0f)
                - Vector3.forward * cannonRecoil;
            cannonSlide.localPosition = Vector3.Lerp(
                cannonSlide.localPosition, target, Time.deltaTime * animationResponse);
        }
    }

    /// <summary>Set an absolute head turn angle in degrees.</summary>
    public void SetHeadYaw(float degrees) { headYawDegrees = Mathf.Clamp(degrees, -90f, 90f); }

    /// <summary>Roll the spiked maul arm independently around its own long axis.</summary>
    public void SetLeftArmRoll(float degrees) { leftArmRollDegrees = degrees; }

    /// <summary>Roll the hammer arm independently around its own long axis.</summary>
    public void SetRightArmRoll(float degrees) { rightArmRollDegrees = degrees; }

    public void SetChestOpen(bool open) { chestOpen = open; }

    /// <summary>
    /// Opens the hatch, pushes the cannon forward, gives it a short recoil, and retracts it.
    /// It does not spawn a projectile; call your game combat code alongside this method.
    /// </summary>
    public void FireCannon()
    {
        if (!firing) StartCoroutine(FireCannonRoutine());
    }

    private IEnumerator FireCannonRoutine()
    {
        firing = true;
        chestOpen = true;
        yield return new WaitForSeconds(0.28f);
        cannonRecoil = 0.18f;
        yield return new WaitForSeconds(0.09f);
        cannonRecoil = 0f;
        yield return new WaitForSeconds(0.48f);
        chestOpen = false;
        firing = false;
    }

    private void ResolvePivots()
    {
        if (headPivot == null) headPivot = FindDeep(transform, "HeadPivot");
        if (leftArmPivot == null) leftArmPivot = FindDeep(transform, "LeftArmPivot");
        if (rightArmPivot == null) rightArmPivot = FindDeep(transform, "RightArmPivot");
        if (chestDoorPivot == null) chestDoorPivot = FindDeep(transform, "ChestDoorPivot");
        if (cannonSlide == null) cannonSlide = FindDeep(transform, "CannonSlide");
        if (pedalDrivePivot == null) pedalDrivePivot = FindDeep(transform, "PedalDrivePivot");
    }

    private static Transform FindDeep(Transform parent, string targetName)
    {
        if (parent.name == targetName) return parent;
        for (int i = 0; i < parent.childCount; i++)
        {
            Transform found = FindDeep(parent.GetChild(i), targetName);
            if (found != null) return found;
        }
        return null;
    }
}
